using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderGizmoOperations:RefCounted
{
    private readonly ActorAnimationOperations _animation=new();private readonly ActorRuntimeOperations _clips=new();private readonly PhysicsSettingsOperations _settings=new();private readonly PowderBridgeOperations _powder=new();
    public void box(GArray lines,Aabb bounds,Transform3D pose){for(int i=0;i<8;i++){var a=bounds.Position+bounds.Size*new Vector3(i&1,(i>>1)&1,(i>>2)&1);for(int axis=0;axis<3;axis++)if((i&(1<<axis))==0){var b=a;b[axis]+=bounds.Size[axis];lines.Add(new[]{pose*a,pose*b});}}}
    public void ring(GArray lines,Transform3D pose,Vector3 half,int axis){var points=new Vector3[49];for(int i=0;i<49;i++){var point=Vector3.Zero;point[(axis+1)%3]=(float)Math.Cos(Math.Tau*i/48)*half[(axis+1)%3];point[(axis+2)%3]=(float)Math.Sin(Math.Tau*i/48)*half[(axis+2)%3];points[i]=pose*point;}lines.Add(points);}
    public void draw(GodotObject spatial,Node3D runtime)
    {
        var actor=runtime.Get("actor").As<Resource>();var editor=spatial.Get("editor").AsGodotObject();double time=editor.Get("canvas").AsGodotObject().Get("playhead").AsDouble();var model=editor.Get("model").AsGodotObject();var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();var values=_animation.sampled_values(actor,_clips.local_time(clip,time));if(!values["powder_show_source"].AsBool())return;var config=_settings.sample(actor,actor.Get("animation_time").AsDouble());var physics=editor.Get("physics").As<RefCounted>();var pose=_powder.source(physics,actor.Get("id").AsString(),config,time);var lines=new GArray();int mode=values["powder_source_mode"].AsInt32(),shape=values["powder_shape"].AsInt32();var dimensions=values["powder_dimensions"].AsVector3();if(mode!=1){if(shape==3){var source=physics.Call("_runtime",values["powder_mesh_actor"].AsString()).AsGodotObject();if(source!=null){var bounds=spatial.Call("bounds",source).AsGodotDictionary();if(bounds.Count>0)box(lines,bounds["box"].AsAabb(),Transform3D.Identity);}}else if(shape==0)box(lines,new Aabb(-dimensions*.5f,dimensions),pose);else{var half=dimensions*.5f;if(shape==1)for(int axis=0;axis<3;axis++)ring(lines,pose,half,axis);else{foreach(float y in new[]{-half.Y,half.Y})ring(lines,pose*new Transform3D(Basis.Identity,new Vector3(0,y,0)),new Vector3(half.X,0,half.Z),1);foreach(double angle in new[]{0,Math.PI*.5,Math.PI,Math.PI*1.5})lines.Add(new[]{pose*new Vector3(half.X*(float)Math.Cos(angle),-half.Y,half.Z*(float)Math.Sin(angle)),pose*new Vector3(half.X*(float)Math.Cos(angle),half.Y,half.Z*(float)Math.Sin(angle))});}}}if(mode!=0){float radius=values["powder_emit_radius"].AsSingle();var direction=values["powder_emit_direction"].AsVector3().Normalized();if(direction.IsZeroApprox())direction=Vector3.Down;var frame=Basis.LookingAt(direction,Math.Abs(direction.Y)>.9?Vector3.Right:Vector3.Up);switch(values["powder_emit_shape"].AsInt32()){case 0:box(lines,new Aabb(-Vector3.One*.025f,Vector3.One*.05f),pose);break;case 1:ring(lines,pose*new Transform3D(frame,Vector3.Zero),Vector3.One*radius,2);break;case 2:var size=values["powder_emit_dimensions"].AsVector3();box(lines,new Aabb(-size*.5f,size),pose);break;case 3:for(int axis=0;axis<3;axis++)ring(lines,pose,Vector3.One*radius,axis);break;}var tip=direction*Math.Max(.4f,radius*2);lines.Add(new[]{pose.Origin,pose*tip});foreach(int sign in new[]{-1,1})lines.Add(new[]{pose*tip,pose*(tip-direction*.1f+frame.X*.06f*sign)});}var camera=spatial.Call("camera").As<Camera3D>();var gizmo=spatial.Get("gizmo").As<CanvasItem>();foreach(var value in lines){var line=value.AsVector3Array();for(int i=0;i<line.Length-1;i++){if(camera.IsPositionBehind(line[i])||camera.IsPositionBehind(line[i+1]))continue;gizmo.DrawLine(spatial.Call("project",line[i]).AsVector2(),spatial.Call("project",line[i+1]).AsVector2(),new Color("d9b477"),1.2f,true);}}
    }
}
